insert into faq (question,answer,sort,active) values
('Как да се включа?','Попълнете формата „Включи се“ на сайта или ни се обадете на 0898 819 299. Ще се свържем с вас, за да уточним удобен час за включване.',0,1),
('Имате ли денонощна поддръжка?','Да. Техническата поддръжка работи 24/7 на 0898 819 299. Екипите ни на терен работят от 09:00 до 19:00 ч.',1,1),
('Как мога да платя сметката си?','Онлайн през бутона „Плати онлайн“, в нашите офиси и каси, в EasyPay, както и по банков път (само за юридически лица).',2,1),
('Има ли такса включване?','Таксата за включване е 15 €. За бизнес плана „Ултра оптичен“ няма такса включване.',3,1),
('Мога ли да спра услугата временно?','Да, предлагаме възможност за временно спиране на услугата. Свържете се с нас за подробности.',4,1),
('Какъв е срокът на договора?','Предлагаме безсрочни договори. Подробностите са в Общите условия.',5,1);
